BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L2 — Clearly trivial threshold application
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinecrest Manufacturing, the engagement team identifies a $75 misstatement in office supplies. Overall materiality is set at $200,000 and the clearly trivial threshold is set at $4,000. Under AU-C 450, the auditor should treat this misstatement by:', '["Not accumulating it because the amount is below the clearly trivial threshold", "Adding it to the summary of uncorrected misstatements for management review", "Reporting it as a significant deficiency to those charged with governance", "Requiring management to correct it before issuing the audit report"]'::jsonb, 0, 'Under AU-C 450.05, auditors need not accumulate misstatements below the clearly trivial threshold. The $75 misstatement falls well below the $4,000 clearly trivial amount, so it does not need to be included on the summary of uncorrected misstatements. Choice B is incorrect because accumulation is only required for misstatements that exceed the clearly trivial threshold, not for every detected error.', 'easy', 2),

-- Q2: hard / L3 — Iron curtain vs rollover approach comparison
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Technology Group, the auditor discovers that revenue was overstated by $40,000 in each of the prior two years, and these misstatements remain uncorrected. The cumulative $80,000 overstatement is now material to the current year balance sheet. Under AU-C 450, the most likely effect of using the iron curtain approach rather than the rollover approach is:', '["A larger tolerable misstatement because cumulative effects are averaged over multiple periods", "A potential modified opinion because the iron curtain approach evaluates the cumulative balance sheet effect", "No difference because both approaches yield identical conclusions for recurring misstatements", "A clean opinion because the individual-year misstatements are each immaterial under the rollover approach"]'::jsonb, 1, 'Under AU-C 450.A18, the iron curtain approach evaluates misstatements based on the cumulative effect on the current period balance sheet, while the rollover approach focuses on the current period income statement effect. Since the cumulative $80,000 is now material to the balance sheet, the iron curtain approach would indicate a potential modified opinion. Choice D is incorrect because the rollover approach, which considers only the current period effect, might not capture the cumulative balance sheet impact that the iron curtain method reveals.', 'hard', 3),

-- Q3: easy / L1 — Deficiency in design definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is a deficiency in design of an internal control?', '["A control that operates inconsistently due to human error during processing", "A control that fails to prevent or detect misstatements only when transaction volumes are high", "A control that is missing or not properly designed to meet a control objective", "A control that was effective in prior years but has not been updated for current risks"]'::jsonb, 2, 'Under AU-C 265.07, a deficiency in design exists when a necessary control is missing or when an existing control is not properly designed to meet the control objective, even if the control operates as designed. Choice A describes a deficiency in operation rather than design, because the control exists and is properly designed but is not being performed effectively by the individuals responsible.', 'easy', 1),

-- Q4: easy / L1 — Clearly trivial definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does "clearly trivial" mean when applied to audit misstatements?', '["Misstatements that are below the performance materiality threshold established for the audit", "Misstatements that management has agreed to correct before the financial statements are finalized", "Misstatements that relate only to disclosures rather than recognized financial statement amounts", "Misstatements that are inconsequential individually and in the aggregate whether judged by size, nature, or circumstances"]'::jsonb, 3, 'Under AU-C 450.A2, clearly trivial is not the same as not material. A matter is clearly trivial when it is inconsequential whether judged by any criteria of size, nature, or circumstances. This threshold is set below performance materiality so that only genuinely inconsequential items are excluded from accumulation. Choice A is incorrect because clearly trivial is a lower threshold than performance materiality, and items between the two thresholds must still be accumulated.', 'easy', 1),

-- Q5: medium / L3 — Qualitative factors affecting materiality
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sterling Financial Advisors, the auditor discovers a $12,000 misstatement that understates management bonuses against overall materiality of $150,000. The misstatement converts a reported net loss into a net profit, triggering management''s performance-based compensation. Under AU-C 450, this finding most likely affects the auditor''s evaluation because:', '["Qualitative characteristics can cause a quantitatively immaterial misstatement to be considered material", "The misstatement must be projected to the population before any qualitative assessment is performed", "Quantitative thresholds always override qualitative considerations in misstatement evaluation", "The misstatement should be reclassified from factual to judgmental based on its effect on compensation"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates whether uncorrected misstatements are material individually or in the aggregate, considering both quantitative magnitude and qualitative factors. A misstatement that changes a loss to a profit and triggers management compensation is qualitatively significant regardless of its dollar amount. Choice C is incorrect because AU-C 450.A16 specifically requires the auditor to consider qualitative factors such as the effect on trends, compliance, and management compensation when evaluating materiality.', 'medium', 3),

-- Q6: medium / L3 — Pervasive misstatement and adverse opinion
(1, 'Misstatements and Control Deficiencies', 'The audit of Northwind Pharmaceuticals reveals uncorrected misstatements totaling $950,000 against overall materiality of $600,000. The misstatements affect revenue recognition, inventory valuation, and accounts receivable—three of the company''s five major account groups. Under AU-C 705, these misstatements most likely support:', '["A qualified opinion because the misstatements exceed materiality in several accounts", "An adverse opinion because the misstatements are both material and pervasive across multiple financial statement elements", "A disclaimer of opinion because the auditor cannot determine the full extent of the misstatements", "An unmodified opinion with an emphasis-of-matter paragraph highlighting the uncorrected misstatements"]'::jsonb, 1, 'Under AU-C 705.08, an adverse opinion is required when misstatements are both material and pervasive to the financial statements. Pervasiveness exists when the misstatements affect multiple elements, accounts, or disclosures, which is the case here with three of five major account groups affected. Choice A is incorrect because a qualified opinion applies when misstatements are material but not pervasive, meaning they are confined to specific elements rather than widespread across the financial statements.', 'medium', 3),

-- Q7: easy / L1 — Summary of uncorrected misstatements purpose
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what is the primary purpose of the summary of uncorrected misstatements?', '["To serve as the basis for adjusting journal entries that management must record", "To document the projected population error rate for statistical sampling purposes", "To accumulate identified misstatements so the auditor can evaluate their aggregate effect on the financial statements", "To provide a schedule of errors for inclusion in the notes to the financial statements"]'::jsonb, 2, 'Under AU-C 450.06, the auditor accumulates all identified misstatements during the audit, other than those that are clearly trivial, on a summary of uncorrected misstatements. This summary allows the auditor to evaluate whether uncorrected misstatements are material individually or in the aggregate. Choice A is incorrect because the summary documents misstatements that management has chosen not to correct, not entries that management must record.', 'easy', 1),

-- Q8: medium / L3 — Recurring misstatements indicating bias or control failure
(1, 'Misstatements and Control Deficiencies', 'Over the past three audits of Granite Peak Industries, the auditor has identified the same type of inventory costing misstatement, each year amounting to approximately $18,000 against materiality of $250,000. Management declines correction each year, calling it immaterial. Under AU-C 450, the recurring nature of this misstatement most likely indicates that:', '["The misstatement should be reclassified from factual to projected because it appears across multiple periods", "The auditor should increase performance materiality to account for the predictable annual error", "The misstatement no longer requires evaluation after three years because management has consistently declined correction", "The auditor should consider whether recurring uncorrected misstatements suggest a systemic control deficiency or management bias"]'::jsonb, 3, 'Under AU-C 450.A18, the auditor considers the implications of uncorrected misstatements from prior periods, including whether recurring patterns indicate a systemic control deficiency or management bias. A repeated inventory costing error suggests a process failure that management has not remediated. Choice A is incorrect because the classification of a misstatement as factual, judgmental, or projected depends on its nature, not on whether it recurs across periods.', 'medium', 3),

-- Q9: easy / L1 — Deficiency in operation definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, what is a deficiency in the operation of an internal control?', '["A properly designed control that does not operate effectively or is not performed by an individual with the necessary authority or competence", "A control that management intentionally bypasses to override established procedures", "A control that functions correctly but addresses risks that are no longer relevant to the entity", "A control that is designed for one objective but is mistakenly applied to a different transaction cycle"]'::jsonb, 0, 'Under AU-C 265.07, a deficiency in operation exists when a properly designed control does not operate effectively, or when the person performing the control lacks the necessary authority or competence to perform it effectively. Choice B is incorrect because management override is a separate fraud risk concept addressed under AU-C 240, not a deficiency in operation of a control under AU-C 265.', 'easy', 1),

-- Q10: medium / L2 — Projected misstatement and tolerable misstatement comparison
(1, 'Misstatements and Control Deficiencies', 'Cascade Valley Textiles has total accounts receivable of $4,200,000. The auditor sets tolerable misstatement at $75,000 and tests a sample of 60 invoices from a population of 1,200. The sample contains confirmed misstatements of $3,800. Under AU-C 530, the auditor should determine the projected misstatement by:', '["Comparing the $3,800 sample misstatement directly to overall materiality without projection", "Extrapolating the sample misstatement to the entire population and comparing the result to the tolerable misstatement", "Limiting the evaluation to only the $3,800 actually found because the sample was randomly selected", "Adding a qualitative allowance to the $3,800 to account for sampling risk without mathematical projection"]'::jsonb, 1, 'Under AU-C 530.13, the auditor projects misstatements found in the sample to the population. The $3,800 error in 60 items must be projected to the full 1,200-item population and compared against the $75,000 tolerable misstatement to evaluate whether the account is materially misstated. Choice C is incorrect because limiting the evaluation to only known sample misstatements ignores the statistical inference that sampling is designed to support.', 'medium', 2),

-- Q11: easy / L1 — Timing of written communication for deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, when must significant deficiencies and material weaknesses be communicated in writing?', '["Within 30 calendar days of the audit report date regardless of the deficiency severity", "Immediately upon discovery during fieldwork before any further audit procedures are performed", "No later than 60 days following the report release date", "Before the start of the subsequent year''s audit engagement"]'::jsonb, 2, 'Under AU-C 265.14, the auditor should communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This timeline ensures timely notification while allowing the auditor to complete the evaluation. Choice A is incorrect because the 60-day period runs from the report release date, not the report date, and the standard does not specify a 30-day window.', 'easy', 1),

-- Q12: medium / L2 — Misstatement in related-party disclosure
(1, 'Misstatements and Control Deficiencies', 'The auditor of Birchwood Hospitality Group determines that a required related-party disclosure omits a $320,000 loan to the CEO''s spouse under ASC 850. Overall materiality is $500,000. Under AU-C 450, the auditor should treat this omission as:', '["An immaterial disclosure deficiency that requires only a management representation letter acknowledgment", "A scope limitation requiring a qualified or disclaimer of opinion under AU-C 705", "An internal control deficiency reportable to the audit committee but not affecting the audit opinion", "A misstatement in disclosure that must be evaluated for materiality considering both quantitative and qualitative factors"]'::jsonb, 3, 'Under AU-C 450.A3, misstatements include inaccuracies or omissions in disclosures. A related-party loan to the CEO''s spouse has qualitative significance because it involves management and related parties, even though the $320,000 amount is below the $500,000 overall materiality. Choice A is incorrect because the qualitative nature of related-party transactions means the auditor cannot dismiss the omission based solely on its dollar amount relative to materiality.', 'medium', 2),

-- Q13: medium / L2 — Sampling risk allowance in misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'While auditing Clearwater Distribution, the auditor uses monetary unit sampling to test $8,500,000 in inventory. The sample identifies pricing errors totaling $6,200. After projection, the likely misstatement is $52,000 against a tolerable misstatement of $60,000. Under AU-C 530, the auditor should evaluate this result by:', '["Comparing the projected likely misstatement of $52,000 plus an allowance for sampling risk against the tolerable misstatement of $60,000", "Comparing only the $6,200 known misstatement to tolerable misstatement because projected amounts are estimates", "Concluding the balance is fairly stated because the likely misstatement of $52,000 is below the $60,000 threshold", "Expanding the sample until the known misstatement exceeds the tolerable misstatement or all items are tested"]'::jsonb, 0, 'Under AU-C 530.13–.14, the auditor must consider both the projected misstatement and the allowance for sampling risk when evaluating sample results. Even though the $52,000 projected misstatement is below the $60,000 tolerable misstatement, adding the sampling risk allowance may push the total above the threshold. Choice C is incorrect because it ignores the allowance for sampling risk, which must be considered alongside the projected misstatement to reach a valid conclusion.', 'medium', 2),

-- Q14: easy / L1 — Management representation letter on uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 580, what must management confirm regarding uncorrected misstatements?', '["That all uncorrected misstatements were caused by employee errors rather than intentional actions", "That management believes the effects of uncorrected misstatements are immaterial individually and in the aggregate", "That management has corrected all material misstatements and will correct remaining items within 90 days", "That the auditor bears responsibility for any misstatements not detected during fieldwork procedures"]'::jsonb, 1, 'Under AU-C 580.11, the auditor requests written representations from management that it believes the effects of uncorrected misstatements aggregated by the auditor are immaterial, individually and in the aggregate, to the financial statements as a whole. A summary of these items is attached to the representation letter. Choice A is incorrect because the representation addresses management''s belief about materiality of uncorrected misstatements, not their underlying cause.', 'easy', 1),

-- Q15: easy / L1 — Written communication format for deficiencies
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which statement best describes the required format for communicating control deficiencies?', '["Significant deficiencies and material weaknesses must be reported using a standardized regulatory form", "All control deficiencies regardless of severity must be communicated in writing to management", "Significant deficiencies and material weaknesses must be communicated in writing to those charged with governance", "Control deficiencies may only be communicated orally and must not be included in any written report"]'::jsonb, 2, 'Under AU-C 265.13, the auditor is required to communicate significant deficiencies and material weaknesses identified during the audit in writing to those charged with governance. This written communication ensures a formal record of the findings and the entity''s accountability for remediation. Choice B is incorrect because AU-C 265 does not require written communication of all deficiencies—only significant deficiencies and material weaknesses require written communication to governance.', 'easy', 1),

-- Q16: medium / L3 — IT general control deficiency effect on application controls
(1, 'Misstatements and Control Deficiencies', 'During the audit of Apex Digital Solutions, the auditor discovers that the IT administrator has both user account creation privileges and system security log review responsibilities. This lack of segregation of duties in IT general controls most likely affects the auditor''s assessment because:', '["IT segregation of duties deficiencies only affect the auditor''s assessment of inherent risk, not control risk", "The deficiency is automatically classified as a material weakness because it involves IT security access", "Manual compensating controls can fully mitigate the deficiency, eliminating any need to modify the audit approach", "The reliability of application controls dependent on these IT general controls may be compromised"]'::jsonb, 3, 'Under AU-C 315.A72, IT general controls support the continued proper functioning of application controls. When IT general controls have a segregation of duties deficiency, the auditor cannot rely on application controls that depend on those general controls, because unauthorized changes could go undetected. Choice B is incorrect because a segregation of duties deficiency in IT is not automatically a material weakness; the auditor must evaluate the severity by considering the likelihood and magnitude of potential misstatement.', 'medium', 3),

-- Q17: medium / L2 — Fraud by senior management communication requirement
(1, 'Misstatements and Control Deficiencies', 'While auditing Redstone Capital Management, the auditor discovers a $28,000 expense reimbursement that the CFO submitted using fabricated receipts. Overall materiality is $400,000. Under AU-C 240, the auditor should communicate this finding to:', '["Those charged with governance regardless of the amount because the fraud involves a member of senior management", "Management only, because the amount is below materiality and does not require governance notification", "The external regulatory authorities directly, bypassing both management and governance", "The entity''s external legal counsel before informing either management or governance"]'::jsonb, 0, 'Under AU-C 240.40, the auditor must communicate fraud involving senior management to those charged with governance on a timely basis, regardless of the amount. Fraud by the CFO represents a failure of integrity in management, which governance must be informed about for oversight purposes. Choice B is incorrect because AU-C 240 requires governance notification whenever fraud involves senior management, even if the dollar amount is immaterial to the financial statements.', 'medium', 2),

-- Q18: hard / L4 — Management bias in one-directional misstatement pattern
(1, 'Misstatements and Control Deficiencies', 'During the audit of Whitehall Property Trust, the auditor identifies eight individually immaterial misstatements totaling $42,000, all overstating revenue through premature recognition. Management declines correction, noting each is immaterial. Overall materiality is $300,000 and performance materiality is $225,000. The pattern involves only one direction of error. Under AU-C 450, the auditor should evaluate management''s position by assessing:', '["Only the quantitative aggregate of $42,000 against performance materiality, as qualitative factors apply only to individual misstatements above the clearly trivial threshold", "Whether the one-directional pattern suggests possible management bias, which may indicate a risk of material misstatement even though the current aggregate is below materiality", "Whether each individual misstatement exceeds the clearly trivial threshold, because the aggregation requirement does not apply when all items are individually immaterial", "Whether the revenue recognition errors would change the entity''s tax liability, as tax effects are the primary qualitative consideration under AU-C 450"]'::jsonb, 1, 'Under AU-C 450.11 and .A18, the auditor must evaluate uncorrected misstatements considering both quantitative and qualitative factors, including indicators of management bias. Eight misstatements all overstating revenue in the same direction suggests potential bias that could signal a broader risk of material misstatement requiring further investigation. Choice A is incorrect because qualitative factors—particularly indicators of possible management bias—must be considered alongside quantitative measures regardless of whether individual amounts exceed the clearly trivial threshold.', 'hard', 4),

-- Q19: easy / L1 — Segregation of duties control deficiency example
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 265, which situation best illustrates a control deficiency related to segregation of duties?', '["A company uses an outdated accounting software system that cannot generate customized reports", "Management has not established a formal code of ethics for the accounting department", "The same employee who records cash receipts also prepares the monthly bank reconciliation", "The company''s external auditor provides both audit and permitted non-audit tax services"]'::jsonb, 2, 'Under AU-C 265.A1, a segregation of duties deficiency exists when incompatible functions are performed by the same individual. The employee who records cash receipts should not also prepare the bank reconciliation, because errors or fraud in cash handling could be concealed through the reconciliation process. Choice B is incorrect because the absence of a code of ethics, while a control environment concern, does not specifically illustrate a segregation of duties deficiency.', 'easy', 1),

-- Q20: medium / L2 — Ratio projection method for sample misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakeside Wholesale Distributors, the auditor selects a random sample of 40 purchase invoices from a population of 2,400 invoices totaling $3,600,000. The sampled invoices total $72,000 and testing reveals overstatements of $2,100. Under AU-C 530, the projected misstatement using the ratio method is:', '["$2,100, limited to the actual errors confirmed in the sample", "$126,000, calculated by multiplying the average error per invoice by the population count", "$52,500, calculated by applying the error rate to half the population value", "$105,000, calculated by applying the sample error rate of 2.917% to the $3,600,000 population"]'::jsonb, 3, 'Under AU-C 530.13, the ratio projection method divides the sample misstatement by the sample dollar value ($2,100 / $72,000 = 2.917%) and applies that rate to the total population value ($3,600,000 x 2.917% = $105,000). This approach is appropriate when misstatements correlate with recorded amounts. Choice B is incorrect because it uses the mean-per-unit method ($2,100 / 40 x 2,400 = $126,000), which projects based on transaction count rather than dollar proportionality.', 'medium', 2),

-- Q21: medium / L2 — Prior period uncorrected misstatement in current evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redwood Consulting Group, the auditor identifies a $55,000 depreciation error originating in the prior year that was not corrected. The error understates accumulated depreciation on the current year balance sheet by $55,000. Overall materiality is $200,000. Under AU-C 450, the auditor should evaluate this prior period misstatement by:', '["Including the $55,000 in the current year summary of uncorrected misstatements because it affects the current year balance sheet", "Excluding the error from the current year evaluation because it was assessed as immaterial in the prior audit", "Requiring a restatement of prior year financial statements before evaluating the current year impact", "Communicating the error to the predecessor auditor for inclusion in their revised working papers"]'::jsonb, 0, 'Under AU-C 450.09, the auditor considers uncorrected misstatements from prior periods that affect current period financial statements. The $55,000 depreciation error continues to understate accumulated depreciation on the balance sheet, so it must be included in the current year''s evaluation of aggregate uncorrected misstatements. Choice B is incorrect because a prior period misstatement that remains uncorrected carries forward and must be reassessed for its cumulative effect on current period financial statements.', 'medium', 2),

-- Q22: medium / L2 — Management bias in accounting estimates
(1, 'Misstatements and Control Deficiencies', 'While auditing Thornberry Insurance Services, the auditor observes that management consistently selects assumptions at the optimistic end of a reasonable range when estimating claims reserves, resulting in reserves 8-12% lower than industry benchmarks each year. Under AU-C 540, the auditor should treat this pattern by:', '["Accepting management''s estimates without further evaluation because each individual estimate falls within a reasonable range", "Evaluating whether the cumulative effect of management''s assumption choices indicates bias that could result in material misstatement", "Requiring management to adopt the midpoint of the reasonable range for all significant accounting estimates", "Reporting the pattern to regulators as potential fraud because consistent optimism violates fair presentation standards"]'::jsonb, 1, 'Under AU-C 540.21, the auditor evaluates whether the judgments and decisions made by management in establishing accounting estimates give rise to indicators of possible management bias. Consistently selecting optimistic assumptions, even within a reasonable range, may indicate bias that could result in material misstatement when considered cumulatively. Choice A is incorrect because the auditor must assess the overall reasonableness of estimates, including whether a pattern of directional bias exists across multiple estimates.', 'medium', 2),

-- Q23: medium / L3 — Net versus gross misstatement evaluation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestline Logistics, the auditor identifies a $65,000 overstatement in accounts receivable and a $60,000 understatement in prepaid expenses. Overall materiality is $100,000. When deciding whether to evaluate these offsetting misstatements on a net or gross basis, AU-C 450 requires the auditor to consider:', '["The net amount of $5,000 because offsetting misstatements within the same financial statements cancel each other", "The gross amount of $125,000 because different account groups should never be netted regardless of circumstances", "Whether the misstatements arise from the same or different causes, as netting is appropriate only for misstatements with a common underlying cause", "The larger individual misstatement of $65,000 because only the most significant error determines the audit conclusion"]'::jsonb, 2, 'Under AU-C 450.A14, when evaluating whether uncorrected misstatements are material, the auditor considers whether netting is appropriate. Misstatements arising from the same underlying cause or process may be appropriately netted, while unrelated misstatements in different accounts should generally be evaluated separately. Choice A is incorrect because automatically netting misstatements that happen to offset on the financial statements ignores that unrelated errors may indicate separate control failures requiring individual evaluation.', 'medium', 3),

-- Q24: medium / L3 — Compensating control effect on deficiency severity
(1, 'Misstatements and Control Deficiencies', 'During the audit of Irongate Manufacturing, the auditor identifies that automated access controls over the inventory system have a design deficiency allowing unauthorized pricing changes. However, a senior manager performs daily manual reviews comparing system prices to the approved vendor price list. Under AU-C 265, the compensating control most likely affects the deficiency classification by:', '["Eliminating the deficiency entirely because the manual review addresses the same risk as the automated control", "Automatically reducing the deficiency from material weakness to significant deficiency by providing detection capability", "Increasing the severity because reliance on manual controls is inherently less reliable than automated controls", "Potentially reducing the severity if the compensating control operates effectively and addresses the same assertion-level risk"]'::jsonb, 3, 'Under AU-C 265.A12, when evaluating the severity of a control deficiency, the auditor considers whether compensating controls effectively address the same financial statement assertion risk. A functioning manual review that compares system prices to approved lists may mitigate the risk of material misstatement, potentially reducing severity. Choice B is incorrect because a compensating control does not automatically change the classification; the auditor must evaluate its operating effectiveness, reliability, and whether it fully addresses the assertion-level risk.', 'medium', 3),

-- Q25: hard / L4 — Aggregate misstatements exceeding performance materiality
(1, 'Misstatements and Control Deficiencies', 'During the audit of Harborview Real Estate Holdings, the auditor accumulates uncorrected misstatements totaling $185,000 against overall materiality of $200,000 and performance materiality of $150,000. The misstatements include a $95,000 revenue overstatement, a $50,000 understatement of property tax accruals, and a $40,000 capitalization overstatement. Management refuses correction. The auditor should evaluate by assessing:', '["Whether the aggregate of $185,000 exceeds performance materiality, and if so, whether further procedures could identify additional misstatements pushing the total above overall materiality", "Only whether the $185,000 aggregate is below the $200,000 overall materiality threshold, because performance materiality is solely a planning tool with no bearing on the opinion", "Whether the individual misstatements can be offset against each other to arrive at a net impact below performance materiality", "Whether reclassifying the misstatements from factual to judgmental would reduce the aggregate below performance materiality"]'::jsonb, 0, 'Under AU-C 450.11, when uncorrected misstatements exceed performance materiality, the auditor should consider extending procedures to determine whether the aggregate is actually material. The $185,000 exceeds the $150,000 performance materiality, indicating a risk that undetected misstatements could push the total above the $200,000 overall materiality. Choice B is incorrect because performance materiality serves as an early warning threshold during evaluation; exceeding it signals that the auditor should perform additional work rather than simply comparing to overall materiality.', 'hard', 4),

-- Q26: hard / L4 — Remediated deficiency reporting assessment
(1, 'Misstatements and Control Deficiencies', 'The internal audit function at Bayshore Financial Group identified a material weakness in the loan approval process three months before the external audit began. Management implemented corrective controls, and internal audit confirmed the new controls operated effectively for the final two months. The external auditor is evaluating whether to report the item as a material weakness. The external auditor should assess:', '["That the deficiency is no longer reportable because internal audit confirmed the remediation was effective", "Whether the remediated control operated for a sufficient period to conclude it was effectively designed and operating, considering that two months may not provide adequate evidence", "That internal audit''s testing substitutes for the external auditor''s evaluation, so no additional procedures are necessary", "That the deficiency must be reported as a material weakness regardless of remediation because it existed during the audit period"]'::jsonb, 1, 'Under AU-C 265.A8, the auditor evaluates whether a remediated deficiency should still be reported by assessing whether the new control operated for a sufficient period to conclude it was effectively designed and operating. Two months of operation may not provide sufficient evidence, particularly for a material weakness in a complex process like loan approvals. Choice D is incorrect because AU-C 265 permits the auditor to conclude a deficiency is no longer reportable if the replacement control has operated long enough to provide sufficient evidence of its effectiveness.', 'hard', 4),

-- Q27: medium / L2 — Communication of non-significant control deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Ridgeway Dental Associates, the auditor identifies three minor control deficiencies: inconsistent use of purchase order numbers, occasional late posting of small cash receipts, and informal approval of office supply purchases under $200. None rises to a significant deficiency. Under AU-C 265, the auditor should communicate these deficiencies by:', '["Including them in the written communication of significant deficiencies to those charged with governance", "Reporting them to the SEC as part of the required internal control assessment under Section 404", "Communicating them to management either orally or in writing as the auditor considers appropriate in the circumstances", "Withholding communication entirely because deficiencies below the significant level have no reporting requirement"]'::jsonb, 2, 'Under AU-C 265.12, the auditor should communicate to management control deficiencies identified during the audit that are not significant deficiencies or material weaknesses but are of sufficient importance to merit management''s attention. This communication may be oral or written. Choice D is incorrect because AU-C 265 encourages communication of other deficiencies to management when they merit attention, even though formal written communication to governance is only required for significant deficiencies and material weaknesses.', 'medium', 2),

-- Q28: medium / L3 — Directional concentration indicating management bias
(1, 'Misstatements and Control Deficiencies', 'During the audit of Briarwood Grocery Cooperative, the auditor accumulates 14 individually immaterial misstatements ranging from $3,000 to $9,000 each. Twelve overstate assets while two understate assets, for a net overstatement of $72,000. Performance materiality is $80,000 and overall materiality is $110,000. Under AU-C 450, the most significant consideration in evaluating the aggregate effect is:', '["That the net overstatement of $72,000 is below performance materiality, confirming no further evaluation is required", "That all 14 misstatements are individually immaterial, so they need not be accumulated on the summary", "That 14 errors suggest expanded sample sizes are needed in the subsequent audit regardless of the current aggregate", "Whether the directional concentration of 12 of 14 misstatements overstating assets indicates management bias requiring further investigation"]'::jsonb, 3, 'Under AU-C 450.A18, the auditor considers whether the nature and pattern of uncorrected misstatements indicate possible management bias. When 12 of 14 individually immaterial misstatements all overstate assets, the directional concentration suggests the errors may not be random, warranting further investigation even though the aggregate remains below performance materiality. Choice A is incorrect because falling below performance materiality does not eliminate the need to evaluate qualitative factors such as directional bias in the pattern of uncorrected misstatements.', 'medium', 3),

-- Q29: hard / L4 — Successor auditor evaluation of predecessor findings
(1, 'Misstatements and Control Deficiencies', 'Mercer & Walsh has been engaged as successor auditor for Pinnacle Logistics, replacing Dalton & Associates. The predecessor''s prior year communication identified a significant deficiency in revenue cutoff procedures. Management claims the deficiency was fully remediated. The successor auditor has not yet tested the remediated controls. Under AU-C 510 and AU-C 265, the successor auditor should evaluate this situation by:', '["Performing procedures to evaluate whether the previously identified significant deficiency has been effectively remediated before relying on the predecessor''s classification", "Accepting the predecessor auditor''s classification and including it unchanged in the current year''s communication to governance", "Relying on management''s assertion that the deficiency was corrected without performing independent testing of the remediated controls", "Communicating with the predecessor auditor to confirm whether the deficiency was remediated before performing any audit procedures"]'::jsonb, 0, 'Under AU-C 510.09 and AU-C 265, the successor auditor has an independent responsibility to evaluate the design and operating effectiveness of internal controls relevant to the audit. A predecessor''s finding informs planning but does not substitute for the successor''s own evaluation. The successor must test whether the remediated controls actually operate effectively. Choice C is incorrect because the auditor cannot rely solely on management''s assertion of remediation without performing independent procedures to verify the new controls are properly designed and operating effectively.', 'hard', 4),

-- Q30: hard / L4 — Remediation timing effect on material weakness reporting
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Mountain Resorts for the year ended December 31, 2025, the auditor identifies a material weakness in payroll authorization in September 2025. Management implements new controls on November 1, 2025, and the auditor tests them, finding them effective for November and December. The auditor''s decision on whether to report this as a material weakness should be based on:', '["Reporting the deficiency as fully remediated because the new controls were effective for the final two months of the fiscal year", "Assessing whether two months of effective operation provides sufficient evidence to conclude the material weakness no longer exists, considering the nature and complexity of the payroll process", "Omitting the deficiency from the written communication entirely because controls must only be evaluated as of the period end date", "Reporting the deficiency as a significant deficiency rather than a material weakness because partial-year remediation automatically reduces severity by one level"]'::jsonb, 1, 'Under AU-C 265.A8, the auditor evaluates whether a remediated deficiency should still be reported by considering whether the replacement control has operated for a sufficient duration. Two months of effective operation may or may not be adequate depending on the nature and complexity of the payroll process, the frequency of transactions processed, and other risk factors. Choice D is incorrect because there is no provision in AU-C 265 that automatically reduces the severity classification based on partial-year remediation; the auditor must exercise professional judgment.', 'hard', 4)
;

COMMIT;
